import{_ as a,c as r,o,a3 as t}from"./chunks/framework.BurWKwwG.js";const p=JSON.parse('{"title":"Search Functionality","description":"","frontmatter":{},"headers":[],"relativePath":"3.2_search.md","filePath":"3.2_search.md"}'),i={name:"3.2_search.md"};function s(l,e,n,c,h,d){return o(),r("div",null,e[0]||(e[0]=[t('<h1 id="search-functionality" tabindex="-1">Search Functionality <a class="header-anchor" href="#search-functionality" aria-label="Permalink to “Search Functionality”">​</a></h1><p>CBD3 provides search capabilities at multiple entry points throughout the platform.</p><h2 id="homepage-search" tabindex="-1">Homepage Search <a class="header-anchor" href="#homepage-search" aria-label="Permalink to “Homepage Search”">​</a></h2><p>The homepage (<code>/</code>) includes a search bar for quick keyword lookup across the biomarker database. Enter a gene symbol, biomarker name, or keyword to jump directly to results.</p><h2 id="biomarker-page-search" tabindex="-1">Biomarker Page Search <a class="header-anchor" href="#biomarker-page-search" aria-label="Permalink to “Biomarker Page Search”">​</a></h2><p>The Biomarker page (<code>/biomarker</code>) provides a search bar for filtering biomarker records. Results are displayed in a paginated table with sortable columns.</p><h2 id="advanced-search" tabindex="-1">Advanced Search <a class="header-anchor" href="#advanced-search" aria-label="Permalink to “Advanced Search”">​</a></h2><p>The Advanced Search page (<code>/search</code>) supports multi-condition queries:</p><ul><li>Add multiple filter conditions across different fields (e.g., biomarker name, gene symbol, cancer type, stage, experiment method)</li><li>Combine conditions with AND/OR logic</li><li><strong>Save Conditions</strong>: Save the current set of search conditions for later use</li><li><strong>Load Conditions</strong>: Reload previously saved search conditions</li></ul><h2 id="gene-autocomplete" tabindex="-1">Gene Autocomplete <a class="header-anchor" href="#gene-autocomplete" aria-label="Permalink to “Gene Autocomplete”">​</a></h2><p>Throughout the platform, gene input fields use autocomplete with the following behavior:</p><ul><li>Type a gene symbol to see matching suggestions from the database</li><li>Autocomplete triggers after a 300ms debounce to reduce server load</li><li>Suggestions are fetched from the backend search API</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><ul><li><strong>No Results</strong>: Try broader terms or check spelling</li><li><strong>Too Many Results</strong>: Add more specific filters</li><li><strong>Slow Performance</strong>: Reduce the search scope by adding filters</li></ul>',14)]))}const u=a(i,[["render",s]]);export{p as __pageData,u as default};
